"use client";

import { ChevronDown } from "lucide-react";
import { useId, useState, type ReactNode } from "react";
import { cn } from "./lib/cn";
import "./shared/accordion-panel.css";
import "./accordion.css";

export type AccordionItem = { id: string; title: string; content: ReactNode; icon?: ReactNode };

export function Accordion({
  items,
  value,
  defaultValue = null,
  onValueChange,
  className,
}: {
  items: readonly AccordionItem[];
  value?: string | null;
  defaultValue?: string | null;
  onValueChange?: (value: string | null) => void;
  className?: string;
}) {
  const [local, setLocal] = useState(defaultValue);
  const openId = value === undefined ? local : value;
  const base = useId();

  function toggle(id: string) {
    const next = openId === id ? null : id;
    if (value === undefined) setLocal(next);
    onValueChange?.(next);
  }

  return (
    <div data-slot="accordion" className={cn("grid max-w-lg", className)}>
      {items.map((item) => {
        const open = openId === item.id;
        const panelId = `${base}-${item.id}`;
        return (
          <div key={item.id} data-slot="accordion-item" data-open={open || undefined}>
            <h3>
              <button
                type="button"
                id={`${panelId}-trigger`}
                aria-expanded={open}
                aria-controls={panelId}
                data-slot="accordion-trigger"
                className="flex min-h-11 w-full items-center gap-3 px-3 py-2 text-left text-sm font-medium outline-none hover:bg-muted/60 focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
                onClick={() => toggle(item.id)}
              >
                {item.icon ? <span className="grid size-7 shrink-0 place-items-center text-muted-foreground">{item.icon}</span> : null}
                <span className="min-w-0 flex-1">{item.title}</span>
                <ChevronDown aria-hidden="true" className="size-4 shrink-0 text-muted-foreground" />
              </button>
            </h3>
            <div id={panelId} role="region" aria-labelledby={`${panelId}-trigger`} data-slot="accordion-panel" data-open={open || undefined} inert={open ? undefined : true}>
              <div className="px-3 pb-3 text-sm leading-6 text-muted-foreground">{item.content}</div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* Shared by accordion.tsx, collapsible.tsx, expandable-card.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="accordion-panel"] {
    display: grid;
    grid-template-rows: 0fr;
    transition: grid-template-rows var(--duration-travel) var(--ease-settle);
  }
  [data-slot="accordion-panel"][data-open="true"] {
    grid-template-rows: 1fr;
  }
  [data-slot="accordion-panel"] > div {
    min-height: 0;
    overflow: hidden;
    opacity: 0;
    transform: translateY(6px);
    transition:
      opacity var(--duration-fast) var(--ease-out),
      transform var(--duration-travel) var(--ease-showcase);
  }
  [data-slot="accordion-panel"][data-open="true"] > div {
    opacity: 1;
    transform: none;
  }
  [data-slot="accordion-trigger"] svg {
    transition: transform var(--duration-travel) var(--ease-showcase);
  }
  [data-slot="accordion-trigger"][aria-expanded="true"] svg {
    transform: rotate(180deg);
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="accordion-panel"] > div {
      transition:
        opacity 120ms var(--ease-out),
        transform 400ms var(--ease-showcase);
    }
    [data-slot="accordion-panel"] {
      transition: grid-template-rows 400ms var(--ease-settle);
    }
    [data-slot="accordion-trigger"] svg {
      transition-duration: 400ms;
    }
  }
}

/* accordion.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="accordion-item"] {
    overflow: hidden;
    border: 1px solid var(--border);
    border-bottom-width: 0;
    background: var(--background);
    transition: margin var(--duration-travel) var(--ease-showcase);
  }
  [data-slot="accordion-item"]:first-child {
    border-start-start-radius: var(--radius-overlay);
    border-start-end-radius: var(--radius-overlay);
  }
  [data-slot="accordion-item"]:last-child {
    border-bottom-width: 1px;
    border-end-start-radius: var(--radius-overlay);
    border-end-end-radius: var(--radius-overlay);
  }
  [data-slot="accordion-item"][data-open="true"] {
    margin-block: 0.5rem;
    border-bottom-width: 1px;
    border-radius: var(--radius-overlay);
  }
  [data-slot="accordion-item"]:has(+ [data-open="true"]) {
    border-bottom-width: 1px;
    border-end-start-radius: var(--radius-overlay);
    border-end-end-radius: var(--radius-overlay);
  }
  [data-slot="accordion-item"][data-open="true"] + [data-slot="accordion-item"] {
    border-start-start-radius: var(--radius-overlay);
    border-start-end-radius: var(--radius-overlay);
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="accordion-item"] {
      transition: margin 400ms var(--ease-showcase);
    }
  }
}
